// Android key attestation chains recorded from real devices, for `android-attest.test.ts`.
//
// SOURCE: the test data of Google's own verifier, github.com/android/keyattestation (`testdata/`), under
// the Apache License 2.0 (Copyright Google LLC) — each chain exactly as a device's Keystore returned it,
// leaf first, with the key description Google's parser read from it (the fields used here). Taken rather
// than synthesised because a verifier tested only against chains its author built agrees with its
// author's misreadings; these were built by the devices.
//
// `at` is an instant inside every certificate's validity (the key's creation where the device recorded
// one): an RKP chain's intermediates live for weeks, and these were recorded long before today.

export type AndroidSample = {
  /** Where it came from, in Google's `testdata/`. */
  source: string;
  /** The chain, leaf first, DER as base64 — what the device sends. */
  chain: string[];
  /** The key description's attestationChallenge, base64. */
  challenge: string;
  /** attestationApplicationId: the package, and the signing certificate digest in assetlinks form. */
  packageName: string;
  signingDigest: string;
  /** An instant every non-leaf certificate is valid at. */
  at: string;
};

